bool optimizer_call_can_inline(const IrFunction* callee) {
  if (callee->blocks.count != 1 || callee->entrypoint != 0)
    return false;

  const IrBlock* body = &callee->blocks.data[0];
  if (body->instructions.count > 12 ||
      body->terminator.type != IR_TERMINATOR_RETURN)
    return false;

  for (size_t i = 0; i < body->instructions.count; i++) {
    const IrInstruction* inst = &body->instructions.data[i];
    // AI generated by: Codex (GPT-6.2-sol)
    // Prompt: "Remove builtin functions from the IR altogether (they should now
    // be handled by lowering to allow for their optimalization, no?). Propagate
    // these changes to the relevant systems (codegen, optimizer)"
    // Changes: Treat every CALL as a user function call.
    if (inst->type == IR_INST_CALL)
      return false;
  }

  return true;
}

// Insert a straight-line callee at the call site and substitute the resulting
// operand.
void optimizer_call_inline_call(Ctx* ctx,
                                IrFunctionId fid,
                                IrBlockId bid,
                                size_t index,
                                const IrFunction* callee) {
  IrFunction* caller = &ctx->ir.functions.data[fid];
  IrInstructionArray* instructions = &caller->blocks.data[bid].instructions;
  IrInstruction call = instructions->data[index];
  size_t previous_count = instructions->count;
  size_t slot_offset = caller->slots.count;
  size_t value_offset = caller->value_count;
  for (size_t i = 0; i < callee->slots.count; i++) {
    const IrStackSlot* slot = &callee->slots.data[i];
    ir_add_slot(ctx, fid, slot->name, slot->type);
  }

  for (size_t i = 0; i < call.operands.call.arg_count; i++) {
    optimizer_call_emit_argument_store(ctx, fid, bid, slot_offset + i,
                                       call.operands.call.args[i]);
  }

  const IrBlock* body = &callee->blocks.data[0];
  for (size_t i = 0; i < body->instructions.count; i++)
    optimizer_clone_instruction(ctx, fid, bid, body->instructions.data[i],
                                value_offset, slot_offset, NULL, 0);

  caller->value_count = value_offset + callee->value_count;

  // The leaf and its argument stores are bounded, so rotation needs no heap
  // allocation.
  IrInstruction expanded[12 + MAX_PARAMETERS];
  size_t count = instructions->count - previous_count;

  memcpy(expanded, instructions->data + previous_count,
         count * sizeof(*expanded));
  ir_free_instruction(&instructions->data[index]);
  memmove(instructions->data + index + count, instructions->data + index + 1,
          (previous_count - index - 1) * sizeof(*expanded));
  memcpy(instructions->data + index, expanded, count * sizeof(*expanded));

  instructions->count--;

  if (call.result != IR_INVALID_ID) {
    IrOperand result = body->terminator.value.return_value;
    optimizer_call_remap_value(&result, value_offset);
    optimizer_replace_value(ctx, fid, call.result, result, false);
  }
}

// Allow a larger clone in a loop, where removing call setup saves work on each
// iteration.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement all"
// Changes: Inline small multi-block functions and join their return paths.
// AI generated by: Codex (GPT-6.2-sol)
// Prompt: "Implement. You can change IR if it improves the results/makes things
// more clear. Also try to split long files (300+) into smaller thematic ones,
// like optimizer was before" Changes: Use a larger growth budget for callees on
// estimated hot paths.
bool optimizer_call_can_inline_cfg(const IrFunction* callee, bool hot) {
  if (callee->blocks.count < 2 || callee->blocks.count > (hot ? 9u : 5u))
    return false;

  size_t count = 0;
  for (size_t b = 0; b < callee->blocks.count; b++) {
    const IrBlock* block = &callee->blocks.data[b];
    count += block->instructions.count;

    if (count > (hot ? 32u : 16u))
      return false;

    for (size_t i = 0; i < block->instructions.count; i++) {
      const IrInstruction* inst = &block->instructions.data[i];

      if (inst->type == IR_INST_CALL)
        return false;
    }
  }

  return true;
}

// Split the caller at the call and route copied return edges to the shared
// continuation.
void optimizer_call_inline_cfg(Ctx* ctx,
                               IrFunctionId fid,
                               IrBlockId bid,
                               size_t index,
                               const IrFunction* callee) {
  IrFunction* caller = &ctx->ir.functions.data[fid];
  size_t slot_offset = caller->slots.count;
  size_t value_offset = caller->value_count;
  IrBlockId first = caller->blocks.count;

  for (size_t b = 0; b < callee->blocks.count; b++)
    ir_add_block(ctx, fid);

  // Move the caller suffix and its terminator together; instruction operands
  // keep their existing ownership.
  IrBlockId continuation = ir_add_block(ctx, fid);
  IrBlock* from = &caller->blocks.data[bid];
  IrBlock* resume = &caller->blocks.data[continuation];
  IrInstruction call = from->instructions.data[index];
  size_t remaining = from->instructions.count - index - 1;

  if (remaining) {
    resume->instructions.data = TRY_MALLOC(remaining * sizeof(IrInstruction));
    memcpy(resume->instructions.data, from->instructions.data + index + 1,
           remaining * sizeof(IrInstruction));
    resume->instructions.capacity = remaining;
    resume->instructions.count = remaining;
    from->instructions.count = index + 1;
  }

  resume->terminator = from->terminator;
  from->terminator = optimizer_call_jump_to(first + callee->entrypoint);

  for (size_t i = 0; i < callee->slots.count; i++) {
    const IrStackSlot* slot = &callee->slots.data[i];
    ir_add_slot(ctx, fid, slot->name, slot->type);
  }

  // All cloned returns use one result slot so the continuation can keep the
  // original call result ID.
  IrStackSlotId result_slot = IR_INVALID_ID;
  if (call.result != IR_INVALID_ID)
    result_slot = ir_add_slot(ctx, fid, "$inline_return", call.result_type);

  for (size_t i = 0; i < call.operands.call.arg_count; i++)
    optimizer_call_emit_argument_store(ctx, fid, bid, slot_offset + i,
                                       call.operands.call.args[i]);

  ir_free_instruction(&from->instructions.data[index]);
  array_remove(ctx, &from->instructions, index);

  for (size_t b = 0; b < callee->blocks.count; b++) {
    const IrBlock* source = &callee->blocks.data[b];
    IrBlockId target = first + b;

    for (size_t i = 0; i < source->instructions.count; i++)
      optimizer_clone_instruction(ctx, fid, target,
                                  source->instructions.data[i], value_offset,
                                  slot_offset, NULL, 0);

    // Local branches stay within the clone. Returns rejoin the caller, while
    // exits keep their terminating behavior.
    IrBlockTerminator term = source->terminator;
    switch (term.type) {
      case IR_TERMINATOR_JUMP:
        term.value.jump_target += first;
        break;

      case IR_TERMINATOR_CONDITIONAL:
        term.value.conditional_target.true_target += first;
        term.value.conditional_target.false_target += first;
        optimizer_call_remap_value(&term.value.conditional_target.condition,
                                   value_offset);
        break;

      case IR_TERMINATOR_RETURN:
        if (result_slot != IR_INVALID_ID) {
          optimizer_call_remap_value(&term.value.return_value, value_offset);
          optimizer_call_emit_argument_store(ctx, fid, target, result_slot,
                                             term.value.return_value);
        }
        term = optimizer_call_jump_to(continuation);
        break;

      case IR_TERMINATOR_EXIT:
        optimizer_call_remap_value(&term.value.exit_code, value_offset);
        break;
    }

    ir_set_terminator(ctx, fid, target, term);
  }

  if (result_slot != IR_INVALID_ID) {
    size_t at = resume->instructions.count;
    ir_add_instruction(ctx, fid, continuation,
                       (IrInstruction){.type = IR_INST_LOAD,
                                       .result_type = call.result_type,
                                       .operands.load.source = result_slot});

    IrInstruction load = resume->instructions.data[at];
    memmove(resume->instructions.data + 1, resume->instructions.data,
            at * sizeof(IrInstruction));
    load.result = call.result;

    resume->instructions.data[0] = load;
  }

  caller->value_count = value_offset + callee->value_count;
}
